      logFinishedStep(
        `Created snapshot export at timestamp ${snapshotExportState.start_ts}`,
      );
      if (snapshotExportDashboardLink !== undefined) {
        logFinishedStep(
          `Export is available at ${snapshotExportDashboardLink}`,
        );
      }
      break;
