export async function dataInDeployment(
  ctx: Context,
  options: {
    deploymentUrl: string;
    adminKey: string;
    deploymentNotice: string;
    tableName?: string | undefined;
    limit: number;
    order: "asc" | "desc";
    component?: string | undefined;
    format?:
      | "json"
      | "jsonArray"
      | "jsonLines"
      | "jsonl"
      | "pretty"
      | undefined;
  },
