      {
        "bearerToken": []
      }
    ],
    "summary": "Update an access group project",
    "tags": [
      "access-groups"
    ],
    "responses": {
      "200": {
        "description": "",
        "content": {
          "application/json": {
            "schema": {
              "properties": {
                "teamId": {
                  "type": "string"
                },
                "accessGroupId": {
                  "type": "string"
                },
                "projectId": {
                  "type": "string"
                },
                "role": {
                  "type": "string",
                  "enum": [
                    "ADMIN",
                    "PROJECT_DEVELOPER",
                    "PROJECT_GUEST",
                    "PROJECT_VIEWER"
                  ]
                },
                "createdAt": {
                  "type": "string"
                },
                "updatedAt": {
                  "type": "string"
                }
              },
              "required": [
                "accessGroupId",
                "createdAt",
                "projectId",
                "role",
                "teamId",
                "updatedAt"
              ],
              "type": "object"
            }
          }
        }
      },
      "400": {
        "description": "One of the provided values in the request body is invalid.\nOne of the provided values in the request query is invalid."
      },
      "401": {
        "description": "The request is not authorized."
      },
      "403": {
        "description": "You do not have permission to access this resource."
      },
      "410": {
        "description": ""
      }
    },
    "parameters": [
      {
        "name": "accessGroupIdOrName",
        "in": "path",
        "required": true,
        "schema": {
          "type": "string"
        },
        "examples": {
          "id": {
            "summary": "Access group ID",
            "value": "ag_1a2b3c4d5e6f7g8h9i0j"
          },
          "name": {
            "summary": "Access group name",
            "value": "My Access Group"
          }
        }
      },
      {
        "name": "projectId",
        "in": "path",
        "required": true,
        "schema": {
          "type": "string"
        },
        "example": "prj_ndlgr43fadlPyCtREAqxxdyFK"
      },
      {
        "description": "The Team identifier to perform the request on behalf of.",
        "in": "query",
        "name": "teamId",
        "schema": {
          "type": "string",
          "example": "REDACTED"
        }
      },
      {
        "description": "The Team slug to perform the request on behalf of.",
        "in": "query",
        "name": "slug",
        "schema": {
          "type": "string",
          "example": "my-team-url-slug"
        }
      }
    ],
    "requestBody": {
      "content": {
        "application/json": {
          "schema": {
            "type": "object",
            "additionalProperties": false,
            "required": [
              "role"
            ],
            "properties": {
              "role": {
                "type": "string",
                "example": "ADMIN",
                "description": "The project role that will be added to this Access Group.",
                "enum": [
                  "ADMIN",
                  "PROJECT_VIEWER",
                  "PROJECT_DEVELOPER",
                  null
                ]
              }
            }
          }
        }
      },
      "required": true
    }
  },
  "post": null
}
